BEGIN READ ONLY; WITH examples(last_date, checked_at, expected_months) AS (VALUES ('2024-03-26'::date, '2026-09-26'::date, 30), ('2025-09-26'::date, '2026-09-26'::date, 12), ('2026-03-26'::date, '2026-09-26'::date, 6), ('2024-02-29'::date, '2026-03-01'::date, 24)) SELECT last_date, checked_at, expected_months, EXTRACT(MONTH FROM AGE(checked_at,last_date))::integer AS previous_value, (12 * EXTRACT(YEAR FROM AGE(checked_at,last_date)) + EXTRACT(MONTH FROM AGE(checked_at,last_date)))::integer AS corrected_value FROM examples; COMMIT;
